import { PORTFOLIOS_TYPES } from 'pages/constants';
import type {
  CountryExportData,
  CountryOverviewData,
  VariationCaption,
} from 'redux/api/bff';

export const applyVariationCaptionTitle = (
  variationCaptions: VariationCaption[] | undefined,
) =>
  variationCaptions?.map((caption) => ({
    ...caption,
    title: 'MB Relevance [%]',
  }));

export const buildEvolutionInfos = (
  overview: CountryOverviewData | undefined,
  megabrands: CountryOverviewData | undefined,
  isLoading: boolean,
) => [
  {
    firstChartData: overview?.yearPowerVsAc,
    secondChartData: overview?.trendOverTime,
    firstChartTitle: 'TT ABI Power',
    secondChartTitle: 'Total ABI Power Trend',
    evolutionSlideLoading: isLoading,
    evolutionSlideError: null,
    evolutionSlideEmpty:
      overview?.yearPowerVsAc?.empty || overview?.trendOverTime?.empty,
  },
  {
    firstChartData: {
      ...megabrands?.yearPowerVsAc,
      variationCaptions: applyVariationCaptionTitle(
        megabrands?.yearPowerVsAc?.variationCaptions,
      ),
    },
    secondChartData: {
      ...megabrands?.trendOverTime,
      variationCaptions: applyVariationCaptionTitle(
        megabrands?.trendOverTime?.variationCaptions,
      ),
    },
    firstChartTitle: 'TT ABI Megabrands Power',
    secondChartTitle: 'Total ABI Megabrands Power Trend',
    evolutionSlideLoading: isLoading,
    evolutionSlideError: null,
    evolutionSlideEmpty:
      megabrands?.yearPowerVsAc?.empty || megabrands?.trendOverTime?.empty,
    portfolioType: PORTFOLIOS_TYPES.MEGABRANDS,
  },
];

export const buildCountrySlideProps = (
  data: CountryExportData | undefined,
  isCompetitor: boolean,
) => ({
  titlePower: isCompetitor ? 'Competitor Power' : 'ABI Power',
  titleBrandBreakdown: isCompetitor
    ? 'Competitor Brand Breakdown'
    : 'ABI Brand Breakdown',
  brandBreakdownKpiData: {
    table: isCompetitor
      ? data?.competitorBrandBreakdown?.brandBreakdown
      : data?.abiBrandBreakdown?.brandBreakdown,
  },
  portfolioPerformanceKpiData: {
    table: data?.summaryPower?.summaryPowerByPortfolioPerformance,
  },
  segmentPerformanceKpiData: {
    table: data?.summaryPower?.summaryPowerBySegmentPerformance,
  },
  competitorView: isCompetitor,
  shouldFilterBreakdownRows: isCompetitor ? false : undefined,
});
